/* Define animation steps using percentages */
@keyframes pulse-glow {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7);
  }
  50% {
    transform: scale(1.05);
    box-shadow: 0 0 0 14px rgba(59, 130, 246, 0);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(59, 130, 246, 0);
  }
}

.live-status-dot {
  width: 20px;
  height: 20px;
  background-color: #3b82f6;
  border-radius: 50%;
  /* Apply animation: name duration timing-function iteration-count */
  animation: pulse-glow 2s infinite ease-in-out;
}

/* Easing determines acceleration and deceleration curves over time */
.btn-spring {
  display: inline-block;
  padding: 12px 24px;
  background-color: #6366f1;
  color: #ffffff;
  border-radius: 8px;

  /* 
   * cubic-bezier(x1, y1, x2, y2): 
   * y-values exceeding 1 create an elastic spring/bounce effect on hover!
   */
  transition: transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1);
}

.btn-spring:hover {
  transform: translateY(-6px) scale(1.04);
}

@keyframes slideFadeUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  opacity: 0; /* Initial state before animation triggers */
  animation: slideFadeUp 0.6s ease-out forwards; /* 'forwards' keeps final state */
}

/* Staggered execution via animation-delay */
.card:nth-child(1) {
  animation-delay: 0.1s;
}

.card:nth-child(2) {
  animation-delay: 0.25s;
}

.card:nth-child(3) {
  animation-delay: 0.4s;
}
